#include <RawPacket.h>
#include <Packet.h>
#include <IPv4Layer.h>
#include <UdpLayer.h>
#include <SomeIpSdLayer.h>
#include <fstream>
#include <vector>
#include <iostream>
#include <iterator>

// Replicate the SomeIP branch of Tests/Fuzzers/ReadParsedPacket.h
static void readParsedPacketSomeIp(pcpp::Packet parsedPacket, pcpp::Layer* layer)
{
	if (parsedPacket.isPacketOfType(pcpp::SomeIP))
	{
		if (auto someipLayer = dynamic_cast<pcpp::SomeIpSdLayer*>(layer))
		{
			auto entries = someipLayer->getEntries();
			if (!entries.empty())
			{
				auto opts = someipLayer->getOptionsFromEntry(0);
				for (auto opt : opts)
					delete opt;
			}

			for (auto entry : entries)
			{
				entry->getNumOptions();
				entry->getServiceId();
				entry->getInstanceId();
				entry->getMajorVersion();
				entry->getMinorVersion();
				entry->getCounter();
				entry->getEventgroupId();
				delete entry;
			}

			someipLayer->getFlags();
			auto opts = someipLayer->getOptions();
			for (auto opt : opts)
			{
				opt->getType();
				if (auto v4opt = dynamic_cast<pcpp::SomeIpSdIPv4Option*>(opt))
				{
					v4opt->getIpAddress();
					v4opt->getPort();
					v4opt->getProtocol();
				}
				else if (auto v6opt = dynamic_cast<pcpp::SomeIpSdIPv6Option*>(opt))
				{
					v6opt->getIpAddress();
					v6opt->getPort();
					v6opt->getProtocol();
				}
				delete opt;
			}
		}
	}
}

int main(int argc, char** argv)
{
	if (argc < 2)
	{
		std::cerr << "usage: local_test <frame.bin>\n";
		return 2;
	}
	std::ifstream f(argv[1], std::ios::binary);
	std::vector<uint8_t> data((std::istreambuf_iterator<char>(f)), std::istreambuf_iterator<char>());
	if (data.empty())
	{
		std::cerr << "empty input\n";
		return 2;
	}
	timeval tv = {0, 0};
	pcpp::RawPacket raw(data.data(), (int)data.size(), tv, false);
	pcpp::Packet parsedPacket(&raw);
	std::cout << parsedPacket.toString() << std::endl;
	auto layer = parsedPacket.getFirstLayer();
	while (layer != NULL)
	{
		std::cout << layer->toString() << std::endl;
		layer->getHeaderLen();
		readParsedPacketSomeIp(parsedPacket, layer);
		layer = layer->getNextLayer();
	}
	parsedPacket.computeCalculateFields();
	return 0;
}

