int main(int argc, char** argv)
{
	if (argc < 2)
	{
		std::cerr << "usage: local_test <pcap-or-frame.bin>\n";
		return 2;
	}
	std::ifstream f(argv[1], std::ios::binary);
	std::vector<uint8_t> fileData((std::istreambuf_iterator<char>(f)), std::istreambuf_iterator<char>());
	if (fileData.empty())
	{
		std::cerr << "empty input\n";
		return 2;
	}

	std::vector<uint8_t> frame;
	bool isPcap = false;
	// detect pcap: magic 0xa1b2c3d4 little endian (d4 c3 b2 a1)
	if (fileData.size() >= 4 && fileData[0] == 0xd4 && fileData[1] == 0xc3 && fileData[2] == 0xb2 && fileData[3] == 0xa1)
	{
		isPcap = true;
		// parse first record
		if (fileData.size() < 24 + 16)
		{
			std::cerr << "truncated pcap\n";
			return 2;
		}
		uint32_t caplen = 0;
		std::memcpy(&caplen, fileData.data() + 24 + 8, 4);
		caplen = ntohl(caplen);
		if (fileData.size() < 24 + 16 + caplen)
		{
			std::cerr << "truncated pcap record, caplen=" << caplen << "\n";
			return 2;
		}
		frame.assign(fileData.begin() + 24 + 16, fileData.begin() + 24 + 16 + caplen);
	}
	else
	{
		frame = fileData;
	}

	// exact-size allocation, like the pcap reader does
	uint8_t* buf = new uint8_t[frame.size()];
	std::memcpy(buf, frame.data(), frame.size());

	timeval tv = {0, 0};
	pcpp::RawPacket raw(buf, (int)frame.size(), tv, true); // deleteRawDataAtDestructor=true
	pcpp::Packet parsedPacket(&raw);
	std::cout << "isPcap=" << isPcap << " frameLen=" << frame.size() << std::endl;
	std::cout << parsedPacket.toString() << std::endl;
	auto layer = parsedPacket.getFirstLayer();
	while (layer != NULL)
	{
		std::cout << layer->toString() << std::endl;
		layer->getHeaderLen();
		readParsedPacketSomeIp(parsedPacket, layer);
		layer = layer->getNextLayer();
	}
	parsedPacket.computeCalculateFields();
	return 0;
}

